<?php namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;class ApiAuthController extends Controller{public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$u=\App\Models\User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password))return response()->json(['message'=>'Invalid credentials'],422);$u->tokens()->delete();$token=$u->createToken($r->input('device_name','mobile'))->plainTextToken;return ['token'=>$token,'user'=>$u];}public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return ['message'=>'Logged out'];}public function user(Request $r){return $r->user();}}
